{!REQUIRESCRIPT("/soap/ajax/24.0/connection.js")} 
{!REQUIRESCRIPT("/soap/ajax/24.0/apex.js")} 
var rtype; 
if('{!Account.RecordType}' == 'Charter Account'){ 
rtype = 'Charters'; 
}
var query = "SELECT Id, Name FROM RecordType where Name like '%"+rtype+"%' AND sObjectType='Opportunity' limit 1"; 
var records = sforce.connection.query(query); 
var records1 = records.getArray('records'); 

var URL; 

if('{!Account.RecordType}' == 'Customer Account'){ 
var URL = 'https://qantas.my.salesforce.com/setup/ui/recordtypeselect.jsp?ent=Opportunity&retURL=%2F{!Account.Id}&save_new_url=%2F006%2Fe%3FretURL%3D%252F{!Account.Id}%26accid={!Account.Id}&00N9000000Dg8jH={!IF(Account.Estimated_Total_Annual_Revenue__c !=0,TEXT(Account.Estimated_Total_Annual_Revenue__c),TEXT(Account.QF_Revenue__c))}&00N9000000EPJxX={!IF(Account.Estimated_MCA_Revenue__c !=0,TEXT(Account.Estimated_MCA_Revenue__c),TEXT(Account.Estimated_MCA_Revenue__c))}&00N9000000Dg8jC={!IF(Account.Estimated_QF_Dom_Market_Share__c !=0,Account.Estimated_QF_Dom_Market_Share__c*100,Account.QF_Domestic_Market_Share__c*100)}&00N9000000Dg8jF={!IF(Account.Estimated_Int_Market_Share__c !=0,Account.Estimated_Int_Market_Share__c*100,Account.QF_International_Market_Share__c*100)}&00N9000000Dg8jE={!IF(Account.Estimated_Int_MCA_Market_Share__c !=0,Account.Estimated_Int_MCA_Market_Share__c*100,Account.QF_International_MCA_Market_Share__c*100)}'; 

}else if('{!Account.RecordType}' == 'Charter Account'){ 
URL = '/006/e?retURL={!Account.Id}&accid={!Account.Id}&RecordType='+records1[0].Id+'&ent=Opportunity'; 
} 
window.top.location.href = URL;
